    "content": "新华社北京11月27日电（记者任军、吴雨）中国人民银行11月27日对外发布《人民币存贷款利率管理规定》，进一步规范存贷款利率管理，旨在促进金融更好支持实体经济、服务人民群众。 随着利率市场化改革不断推进，制定于20多年前的《人民币利率管理规定》，已不能完全适应存贷款利率管理工作的新形势。此外，多类存贷款利率规定散落在不同文件中，不利于实现利率工作的统一管理。 中国人民银行以《人民币利率管理规定》为主体，结合其他文件中的人民币存贷款计结息有关规定，修订形成新规。主要变化体现在三个方面。 一是罚息利率由借贷双方协商确定…"
