    "content": "11月27日，国务院常务会议研究持续深化资本市场投融资综合改革工作。会议明确要加力发挥“国家队”稳市作用，进一步优化中央汇金公司的类“平准基金”功能，提供充足流动性保障。 澎湃新闻记者获悉，“国家队”入市护盘过程中，各类稳定资金、中长期资金积极入市，两项稳市货币政策工具持续落地显效，稳市合力不断增强。10月初以来公募基金、券商自营、私募证券基金、社保基金、保险机构等均表现为净买入，专业机构正加大逆周期布局力度。 据统计，10月初以来A股市场波动过程中，股票型ETF净申购近8000亿元，总规模快速增长至2.9万亿元。…"
