    "description": "中国共产党江苏省第十五届委员会第一次全体会议11月27日选举信长星为省委书记，刘小涛、范波为省委副书记，当选为省委常委的还有周红波、张文兵、胡立杰（女）、边学文、李耀光、陈忠伟、马士光、沈剑荣、敬健、吴庆文。 中国共产党江苏省第十五届纪委第一次全体会议选举边学文为省纪委书记，陆野、黄楚中、祁新、王巨兵为省纪委副书记。",
    "content": "中国共产党江苏省第十五届委员会第一次全体会议11月27日选举信长星为省委书记，刘小涛、范波为省委副书记，当选为省委常委的还有周红波、张文兵、胡立杰（女）、边学文、李耀光、陈忠伟、马士光、沈剑荣、敬健、吴庆文。 中国共产党江苏省第十五届纪委第一次全体会议选举边学文为省纪委书记，陆野、黄楚中、祁新、王巨兵为省纪委副书记。"
