    "content": "A股“股王”贵州茅台拟中期分红320亿元。 11月27日晚间，贵州茅台酒股份有限公司（贵州茅台，600519.SH）披露2026年中期利润分配方案，公司向全体股东每股派发现金红利25.60元（含税）。截至2026年10月31日，公司总股本约为12.5亿股，以此计算合计派发现金红利约320.02亿元（含税）。 根据公告，截至2026年9月30日，贵州茅台母公司报表中未分配利润约为1610.69亿元。本次利润分配方案综合考虑了公司目前的生产经营状况、未来发展资金需求、经营现金流等因素，不会对公司正常经营和长期发展造成影…"
