    "content": "又有一所高校向师生提供免费词元（Token）。 2026年11月27日，复旦大学宣布，面向全校师生免费开放大模型API服务，每人每周初始配额为1亿Token。在此之前，上海已有多所高校向师生开放了词元额度。同济大学人工智能服务平台为每位师生提供专属API Key，平台上线后每周1000积分(折合约1亿词元)。华东师范大学走的是“免申请直发”路线，基础词元配额直接发放至学校AI平台个人账户，科研竞赛项目可再申请专项大额额度。沪上高校中额度最高的是上海交通大学，“交我算”平台提供的词元额度为每周10亿。值得注意的是，每…"
