    "author": "",
    "description": "加沙地带（资料图） 当地时间27日，总台记者获悉，巴勒斯坦伊斯兰抵抗运动（哈马斯）高级官员纳伊姆证实，哈马斯领导人哈亚的儿子当天凌晨在加沙城里马尔社区一处公寓遭以军空袭，但本人及其家人均在袭击中幸存。 纳伊姆表示，以军此次袭击行径属于“国家恐怖主义”。他表示，只要以色列方面持续采取此类行动且未受追究，中东地区就无法实现任何真正的安全与稳定。",
