    "content": "新华社北京11月27日电 题：天宫日记：离开地球的48小时 贾淑宜、米思源、李芮 在距离地球400多公里的空间站内，每隔约90分钟就能看见一次日出。11月27日8时18分，神舟二十四号乘组航天员穆罕默德·齐尚·阿里已经经历数十次日出。此时，这位首次飞天的巴基斯坦航天员离开地球不过短短48小时。 在这离开地球的48小时里，他的人生“第一次”不断刷新。 自火箭起飞后，齐尚·阿里就一直在期待那个独属于太空的奇妙瞬间。 火箭还在持续加速过程中，齐尚·阿里便迫不及待地试着将手中的签字笔轻轻抛起。 不过，笔又快速落回掌心。此时…"
