    "description": "桥板断裂、桥墩附着大量福寿螺卵、文物保护单位标志碑缺失……在上海市闵行区，两座有着百余年历史的古桥未得到有效保护、状况堪忧。 2026年11月27日，澎湃新闻记者从上海市闵行区人民检察院（以下简称闵行区检察院）获悉，近日，该院通过制发检察建议，推动古桥得到有效保护，以实际行动守护城市文脉。 在闵行区一河道上，两座平梁桥始建于清代，通体由花岗石砌筑而成，桥身两侧阳刻楷体桥额，已历经两个多世纪风雨洗礼。6月23日，闵行区检察院公益诉讼检察官…",
    "content": "桥板断裂、桥墩附着大量福寿螺卵、文物保护单位标志碑缺失……在上海市闵行区，两座有着百余年历史的古桥未得到有效保护、状况堪忧。 2026年11月27日，澎湃新闻记者从上海市闵行区人民检察院（以下简称闵行区检察院）获悉，近日，该院通过制发检察建议，推动古桥得到有效保护，以实际行动守护城市文脉。 在闵行区一河道上，两座平梁桥始建于清代，通体由花岗石砌筑而成，桥身两侧阳刻楷体桥额，已历经两个多世纪风雨洗礼。6月23日，闵行区检察院公益诉讼检察官在排查辖区文物保护领域线索时发现，其中一座古桥桥墩上附着大量福寿螺卵，桥下河水中…"
