    "pub_date": "2026-11-27 21:17:22",
    "author": "",
    "description": "击球垫收起，指示牌拆除，原本接待高尔夫球客的员工，如今每隔几分钟就要接听一通会员询问退款的电话。 这是法新社记者星期四（11月26日）在北京东枫国际体育园高尔夫练习场看到的一幕。 园方当天公告，根据相关部门要求，练习场已于星期三（25日）起停止运营。一名自2016年起就在这里工作的员工说，练习场并不缺少愿意花数千元人民币（1000元人民币约等于193新元）购买数月会籍的会员，但对于突然停业，他所知道的也仅限于网上公告。",
