    "description": "中新网广州11月27日电 (记者 方伟彬)记者27日从广州仲裁委员会获悉，日前，该委员会代表团赴澳大利亚、新西兰访问交流，在墨尔本、奥克兰分别揭牌设立广州国际仲裁院澳大利亚联络办公室、新西兰联络办公室，并与新西兰国际仲裁中心签署合作备忘录。至此，该委员会已在海外设立1处庭审中心和5处联络办公室。",
    "content": "中新网广州11月27日电 (记者 方伟彬)记者27日从广州仲裁委员会获悉，日前，该委员会代表团赴澳大利亚、新西兰访问交流，在墨尔本、奥克兰分别揭牌设立广州国际仲裁院澳大利亚联络办公室、新西兰联络办公室，并与新西兰国际仲裁中心签署合作备忘录。至此，该委员会已在海外设立1处庭审中心和5处联络办公室。"
