    "content": "北京实施无人机“全域禁存”新规近两周，当地警方已查获多起违规案件，其中一名外籍旅客携带四架无人机经北京转机出境，被没收无人机及罚款。 北京首都机场公安局星期五（11月27日）在微信公众号公布三起典型案例。其中一名外籍旅客携带四架无人机从中国境内某机场乘机抵京，计划在北京转机出境。 出发地机场警方曾劝阻这名旅客，并告知北京无人机管理新规，但旅客仍坚持携带无人机进京，最终被首都机场警方没收无人机及罚款。 另一起案件中，吕姓旅客从北京市区前往首都机场准备乘机离京，在办理登机手续时被发现携带一架无人机。吕姓旅客称，无人机是…"
