    "description": "人工智能和计算基础设施开发商LIAN Group已选择伦敦作为明年潜在首次公开募股(IPO)的地点，这可能为当地低迷的新股市场带来提振。LIAN之前考虑在欧洲或美国上市，可能募资约5亿美元，这一募资规模目前没有变化，IPO暂定于2027年上半年进行。（财联社）",
