    "content": "新华社广州11月27日电 2026年世界中学生夏季运动会中国中学生体育代表团27日成立，将派出85名运动员参加将于当地时间12月3日在巴西里约热内卢揭幕的本届赛事。 据悉，中国代表团由148人组成，其中85名运动员来自全国22个省（区、市）的62所学校，将参加田径、沙滩排球、摔跤、柔道、跆拳道、空手道、国际象棋7个大项、74个小项的比赛。教育部学生体育协会联合秘书处副秘书长、中国学生体育联合会副主席满开杰担任代表团团长。中国学生体育联合会于今年5月启动选拔工作，在参考往年竞赛成绩的基础上，组织了7个参赛项目的选拔赛…"
