    "content": "36氪获悉，11月27日晚，美团三季度财报电话会上，CEO王兴表示，“AI要真正创造价值，关键在于将高价值场景、高质量数据和闭环执行能力深度结合，这正是美团的优势所在。”在用户侧，美团AI管家“小团”的理解和执行能力进一步提升，越来越多用户在日常场景中，习惯通过“小团”解决各类消费需求。国庆期间，“小团”用户量和调用量较五一假期增长超六成。在商家侧，美团推出AI经营工作台“妙手”（CatPaw），目前已服务超过200万商家。王兴进一步补充，今年我们通过AI相关的资本支出订单锁定了部分算力用于未来使用，因此我们预计明…"
