    "description": "新华社济南11月27日电 针对媒体反映的山东高速信息集团有限公司承建的某新基建项目存在监测设备混凝土底座质量缺陷等问题，山东省成立的联合调查组27日发布情况通报称，部分混凝土底座强度不足的问题属实，项目存在建设单位主体责任缺失、设计深度不够、施工单位违法分包、监理和检测流于形式等问题。 通报称，山东省成立由省发展改革委、省住房城乡建设厅、省交通运输厅、省国资委等部门组成的联合调查组，综合采取现场勘验、调查取证、取样鉴定、技术分析、专家论…",
    "content": "新华社济南11月27日电 针对媒体反映的山东高速信息集团有限公司承建的某新基建项目存在监测设备混凝土底座质量缺陷等问题，山东省成立的联合调查组27日发布情况通报称，部分混凝土底座强度不足的问题属实，项目存在建设单位主体责任缺失、设计深度不够、施工单位违法分包、监理和检测流于形式等问题。 通报称，山东省成立由省发展改革委、省住房城乡建设厅、省交通运输厅、省国资委等部门组成的联合调查组，综合采取现场勘验、调查取证、取样鉴定、技术分析、专家论证等方式，开展深入调查。 关于监测设备混凝土底座施工质量问题，联合调查组委托建研…"
