    "content": "36氪获悉，中国人民银行发布《中国金融稳定报告（2026）》。其中提到，“十五五”时期我国发展环境面临深刻复杂变化，战略机遇和风险挑战并存、不确定难预料因素增多。我国经济基础稳、优势多、韧性强、潜能大，长期向好的支撑条件和基本趋势没有变，推动高质量发展的要素条件不断集聚增多。下一步，金融系统将坚持以习近平新时代中国特色社会主义思想为指导，全面贯彻落实党的二十大和二十届历次全会精神，深入学习贯彻中央经济工作会议、中央金融工作会议和全国金融系统工作会议精神，坚持防风险、强监管、促高质量发展工作主线，持续防范化解重点领域…"
