    "content": "36氪获悉，中国人民银行发布《中国金融稳定报告（2026）》。其中提到，下一步，金融系统将灵活高效运用多种货币政策工具，保持流动性充裕，保持社会融资条件相对宽松。坚持市场在汇率形成中的决定性作用，保持汇率弹性，加强预期引导，保持人民币汇率在合理均衡水平上的基本稳定。统筹做好金融“五篇大文章”，聚焦支持扩大内需、科技创新和中小微企业等重点领域，完善政策框架，提升金融服务实体经济高质量发展质效。健全覆盖全面的宏观审慎管理体系，加强系统性金融风险的监测评估，完善宏观审慎和金融稳定管理工具箱。推动金融服务业和金融市场的高水…"
