    "content": "寒潮接连自北向南影响我国，供暖季如期开启。这个冬天，从核能、地热到风光绿电，热源有了不少“新面孔”，保暖保供实力更强。 10月31日，国家电投山东海阳核电5号机组核岛开始浇筑第一罐混凝土，标志着海阳核电项目三期工程正式开工建设。新华社发（唐克 摄） 在山东海阳，为居民家中供暖的“锅炉房”，是一座核电站。 国家电投“暖核一号”核能供热项目近期开启第八个供暖季，覆盖海阳、乳山两个城区，供热面积1400万平方米，是国内首个、目前规模最大的核能供热工程。 从发电到供热，核电站不再只是电源，也成为零碳热源——发电同时，热量经…"
