    "description": "中国海警局新闻发言人姜略表示，11月26日，日本“第三奖弥丸”号渔船非法进入中国钓鱼岛领海，中国海警舰艇依法对其采取必要管控措施并警告驱离。钓鱼岛及其附属岛屿是中国固有领土，我们敦促日方立即停止在该海域的一切侵权挑衅行径。中国海警将持续在钓鱼岛及其附属岛屿领海内开展维权执法，维护国家领土主权和海洋权益。",
