    "author": "",
    "description": "中新网济南11月27日电 (李明芮)记者11月27日从山东省人民政府新闻办公室召开的发布会上获悉，今年，山东省政协十三届四次会议重点提案督办带动同类提案联动办理工作，是在去年试点的基础上建立的一项创新性机制。目前，山东省领导领办督办的17件重点提案及联动办理的42件同类提案均已全部办复，答复满意率100%，顺利完成了督办任务。",
    "content": "中新网济南11月27日电 (李明芮)记者11月27日从山东省人民政府新闻办公室召开的发布会上获悉，今年，山东省政协十三届四次会议重点提案督办带动同类提案联动办理工作，是在去年试点的基础上建立的一项创新性机制。目前，山东省领导领办督办的17件重点提案及联动办理的42件同类提案均已全部办复，答复满意率100%，顺利完成了督办任务。"
