    "content": "新华社哈瓦那11月26日电 通讯｜在缅怀中激励——古巴纪念菲德尔·卡斯特罗逝世十周年 新华社记者蒋彪 吴昊 26日晚，古巴哈瓦那大学门前人头攒动，大批古巴民众聚集于此，谈历史，谈精神，谈缅怀，谈现实困难，谈国家尊严，谈发展希望，以此纪念革命领袖菲德尔·卡斯特罗逝世十周年。国家主席迪亚斯-卡内尔等古巴党政领导人出席活动。 菲德尔·卡斯特罗1950年毕业于哈瓦那大学法律专业，获法学博士学位。他曾说，就是在这所大学，“我成为一个革命者”。1959年他领导古巴革命，推翻了巴蒂斯塔独裁政府，成立革命政府。几十年来，菲德尔·卡…"
