    "content": "近日，国家网信办、中央编办、工业和信息化部、公安部、交通运输部、中国人民银行、海关总署、税务总局、市场监管总局、国家外汇局、国家密码管理局联合公布《分布式数字身份互通互认应用规定》（以下简称《规定》），自2027年3月1日起施行。 《规定》贯彻落实党中央、国务院决策部署，旨在促进分布式数字身份创新发展与互通互认应用，建立健全分布式数字身份公共服务体系，支撑国家区块链网络基础共性服务能力建设。 《规定》明确了分布式数字身份互通互认应用的基本原则、各参与方的概念定义等，提出鼓励多元主体参与分布式数字身份体系建设，形成可…"
