    "content": "新华社兰州11月27日电 甘肃省纪委监委27日通报，经甘肃省委批准，甘肃省纪委监委对甘肃省建设投资（控股）集团有限公司原副总经理李文恩严重违纪违法问题进行了立案审查调查。 经查，李文恩身为党员领导干部，丧失理想信念，背弃初心使命，对党不忠诚不老实，伪造证据，对抗组织审查；罔顾中央八项规定精神，违规收受礼金，接受可能影响公正执行公务的宴请；无视组织原则，不如实报告个人有关事项；违规经商办企业；贪婪无度，利用职务便利伙同他人侵吞公款；利欲熏心，把公权力当作谋取私利的工具，大搞权钱交易，利用职务便利为他人在物资供应、工程…"
