    "description": "中国人民银行公告〔2026〕第30号 为促进大额存单市场健康发展，中国人民银行制定了《大额存单管理办法》，现予公布，自2027年3月21日起施行。 附件：大额存单管理办法 中国人民银行 2026年11月26日 附件 大额存单管理办法 第一条 为规范大额存单业务发展，根据《中华人民共和国中国人民银行法》等法律法规，制定本办法。 第二条 本办法所称大额存单是指由银行业存款类金融机构面向非金融机构投资人发行的记账式大额存款凭证。 发行大额存单…",
    "content": "中国人民银行公告〔2026〕第30号 为促进大额存单市场健康发展，中国人民银行制定了《大额存单管理办法》，现予公布，自2027年3月21日起施行。 附件：大额存单管理办法 中国人民银行 2026年11月26日 附件 大额存单管理办法 第一条 为规范大额存单业务发展，根据《中华人民共和国中国人民银行法》等法律法规，制定本办法。 第二条 本办法所称大额存单是指由银行业存款类金融机构面向非金融机构投资人发行的记账式大额存款凭证。 发行大额存单的银行业存款类金融机构（以下称发行人）包括政策性银行、商业银行、农村信用合作社以…"
