    "description": "中国人民银行令〔2026〕第5号（人民币存贷款利率管理规定） 《人民币存贷款利率管理规定》已经2026年10月30日中国人民银行第10次行务会审议通过，现予发布，自2027年3月21日起施行。 行长 潘功胜 2026年11月26日 人民币存贷款利率管理规定 第一章 总则 第一条 为有效发挥存、贷款利率对市场经济的调节作用，维护正常的金融秩序，创造公平有序的竞争环境，根据《中华人民共和国中国人民银行法》《中华人民共和国商业银行法》及其他相…",
