    "content": "新华社巴黎11月27日电（记者崔可欣）法国国家统计和经济研究所27日公布的修正数据显示，今年第三季度法国国内生产总值环比下降0.2%，降幅较此前公布的初步数据扩大0.1个百分点。 今年第一季度，法国经济环比萎缩0.2%，第二季度陷入停滞，第三季度再度萎缩，经济增长持续乏力。 数据显示，第三季度法国投资持续疲软。法国国家统计和经济研究所指出，此次下修第三季度经济增长数据，主要是因为建筑领域投资表现较此前估算更为疲弱，信息通信领域投资表现也不及预期。 此外，法国公共财政压力进一步加大。在公共财政收入增长放缓的同时，公共…"
