    "content": "新华社苏瓦11月27日电（记者白涌泉 郭鑫惠）努库阿洛法消息：中国第七批援汤加医疗队27日走进汤加努库阿洛法市科洛瓦伊社区开展义诊，带来针灸、推拿、拔罐等传统中医疗法。 在义诊现场，中医诊疗专区吸引大量民众前来问诊、治疗。据医疗队队长孙晓鹏介绍，本批援汤加医疗队由9名队员组成，涵盖麻醉、中医、耳鼻喉等医疗专业。医疗队发挥专业资源优势，将中医药诊疗服务引入汤加基层社区。 科洛瓦伊社区负责人雷娅表示，汤加基层医疗资源薄弱，民众就医渠道有限，中国医疗队走进社区开展义诊，有效缓解当地人看病难的问题。 2018年以来，中国已…"
