    "description": "最高人民法院日前对纷美包装、新巨丰诉利乐中国滥用市场支配地位两案二审宣判，判令利乐合计赔偿4.92亿元。这是2016年监管部门对利乐作出垄断行政处罚之后，受损竞争者通过民事途径获赔，行政执法与民事追责顺畅衔接，是我国竞争法治进程中一个扎实的样本。 回溯源头，当年调查查实，利乐在液体食品无菌包装相关市场具备支配地位，依靠搭售、限定交易、忠诚折扣等手段锁定客户、排挤同行，监管部门依法开出罚单。利乐接受处罚后，国内同行提起索赔，案件历经多年审…",
    "content": "最高人民法院日前对纷美包装、新巨丰诉利乐中国滥用市场支配地位两案二审宣判，判令利乐合计赔偿4.92亿元。这是2016年监管部门对利乐作出垄断行政处罚之后，受损竞争者通过民事途径获赔，行政执法与民事追责顺畅衔接，是我国竞争法治进程中一个扎实的样本。 回溯源头，当年调查查实，利乐在液体食品无菌包装相关市场具备支配地位，依靠搭售、限定交易、忠诚折扣等手段锁定客户、排挤同行，监管部门依法开出罚单。利乐接受处罚后，国内同行提起索赔，案件历经多年审理，二审敲定赔偿金额。 竞争是市场经济的基石，垄断是市场经济的大敌。行政处罚重在…"
