    "content": "新华社悉尼11月27日电 通讯丨“你们早已成为我们的家人” 新华社记者张淑惠 梁有昶 11月底，位于太平洋中部的岛国基里巴斯依然烈日高照，第五批中国援基里巴斯医疗队即将完成为期一年的援外医疗任务。医疗队队长唐晓杰正拿着一本刚制作好的《汤格鲁中央医院工作手册》，给当地医护人员仔细讲解。 这本手册是第五批中国援基医疗队留给基里巴斯的一份特殊礼物。手册结合当地疾病特点和实际医疗需求，凝聚了中国医疗队专业临床经验，为当地医护人员提供规范化的临床工作参考。这项工作得到基卫生部的高度重视，卫生部长布斯·纳万亲自为手册作序。 基…"
